function gp_create_blog_posts() {
    if (get_option('gp_blog_posts_v1')) return; // already run once — never re-run automatically
    foreach (gp_blog_posts_data() as $p) {
        $existing = get_page_by_path($p['slug'], OBJECT, 'post');
        if ($existing) continue; // don't touch/duplicate a post that already exists
        $post_id = wp_insert_post([
            'post_type'    => 'post',
            'post_status'  => 'publish',
            'post_title'   => $p['title'],
            'post_name'    => $p['slug'],
            'post_content' => $p['content'],
            'post_excerpt' => $p['meta_desc'],
        ]);
        if ($post_id && !is_wp_error($post_id)) {
            // Pre-fill Yoast's fields too, so there's no blank-description
            // gap even before anyone opens the post in wp-admin.
            update_post_meta($post_id, '_yoast_wpseo_title', $p['seo_title']);
            update_post_meta($post_id, '_yoast_wpseo_metadesc', $p['meta_desc']);
            update_post_meta($post_id, '_yoast_wpseo_focuskw', $p['focus_kw']);
        }
    }
    update_option('gp_blog_posts_v1', true);
}
add_action('init', 'gp_create_blog_posts', 30);

// ── FEATURED IMAGES FOR BLOG POSTS ──────────────────────────────────────────
// Runs on every load (cheap — one quick has_post_thumbnail() check per post)
// rather than being gated by the once-only flag above, so this also works
// correctly if the posts were already created by an earlier theme version
// before these images existed.
function gp_blog_featured_images_map() {
    return [
        'how-to-fix-a-leaking-geyser'             => 'how-to-fix-a-leaking-geyser-v2.jpg',
        'signs-of-a-blocked-drain'                => 'signs-of-a-blocked-drain-v2.jpg',
        'load-shedding-and-your-geyser'           => 'load-shedding-and-your-geyser-v2.jpg',
        'what-is-a-pirb-compliance-certificate'   => 'what-is-a-pirb-compliance-certificate.jpg',
        'how-to-choose-the-right-geyser-size'     => 'how-to-choose-the-right-geyser-size.jpg',
        'common-plumbing-problems-in-older-homes' => 'common-plumbing-problems-in-older-homes.jpg',
    ];
}

function gp_set_blog_featured_images() {
    if (!function_exists('wp_upload_bits')) require_once ABSPATH . 'wp-admin/includes/file.php';
    if (!function_exists('wp_generate_attachment_metadata')) require_once ABSPATH . 'wp-admin/includes/image.php';
    if (!function_exists('media_handle_sideload')) require_once ABSPATH . 'wp-admin/includes/media.php';

    $kw_map = [];
    foreach (gp_blog_posts_data() as $p) { $kw_map[$p['slug']] = $p['focus_kw']; }

    foreach (gp_blog_featured_images_map() as $slug => $filename) {
        $post = get_page_by_path($slug, OBJECT, 'post');
        if (!$post) continue; // post doesn't exist yet

        // Only (re)upload if this exact source file hasn't already been set
        // as the thumbnail. This lets photos be swapped later (edit the map
        // above, re-upload the theme) without leaving stale images in place,
        // while still avoiding re-uploading the same file on every request.
        $current_source = get_post_meta($post->ID, '_gp_blog_featured_source', true);
        if ($current_source === $filename && has_post_thumbnail($post->ID)) continue;

        $file_path = get_template_directory() . '/assets/blog/' . $filename;
        if (!file_exists($file_path)) continue;

        $upload = wp_upload_bits($filename, null, file_get_contents($file_path));
        if ($upload['error']) continue;

        $attachment = [
            'post_mime_type' => 'image/jpeg',
            'post_title'     => sanitize_file_name(pathinfo($filename, PATHINFO_FILENAME)),
            'post_status'    => 'inherit',
        ];
        $attach_id = wp_insert_attachment($attachment, $upload['file'], $post->ID);
        if (is_wp_error($attach_id)) continue;

        $attach_data = wp_generate_attachment_metadata($attach_id, $upload['file']);
        wp_update_attachment_metadata($attach_id, $attach_data);

        // Alt text = the post's focus keyphrase — directly resolves the
        // "keyphrase in image alt attributes" Yoast flag with no manual work.
        $alt = $kw_map[$slug] ?? get_the_title($post->ID);
        update_post_meta($attach_id, '_wp_attachment_image_alt', $alt);

        set_post_thumbnail($post->ID, $attach_id);
        update_post_meta($post->ID, '_gp_blog_featured_source', $filename);
    }
}
add_action('init', 'gp_set_blog_featured_images', 31);
